/* cpr/cprver.h — normally generated by cpr's CMake from cmake/cprver.h.in.
 *
 * Four constants derived from cpr's project() version. Vendored rather than
 * templated at build time because that is the entire content of the generated
 * file, and nothing here reads it except cpr's own version accessor.
 *
 * The value is what cpr 1.11.2's CMakeLists declares: project(cpr VERSION
 * 1.11.1). The mismatch with the tag is upstream's, and the CMake build
 * produced exactly this.
 */
#ifndef CPR_CPRVER_H
#define CPR_CPRVER_H

#define CPR_VERSION "1.11.1"

#define CPR_VERSION_MAJOR 1
#define CPR_VERSION_MINOR 11
#define CPR_VERSION_PATCH 1

#define CPR_VERSION_NUM 0x10b01

#endif
